import unittest

from hourglass.errors import ProjectError
from hourglass.models import Shift, Span
from hourglass.timesheet import timesheet_lines


def make_shift(worker, day, start, end):
    return Shift(worker, day, Span(start * 60, end * 60))


class TimesheetTests(unittest.TestCase):
    def test_busiest_first(self):
        lines = timesheet_lines([
            make_shift("Ana", "mon", 9, 12),
            make_shift("Brisa", "mon", 8, 16),
            make_shift("Ana", "tue", 9, 12)
        ])
        self.assertEqual(lines, [
            "Brisa: 1 shift, 8.0 hours",
            "Ana: 2 shifts, 6.0 hours"
        ])

    def test_one_decimal_place(self):
        shift = Shift("Ana", "mon", Span(540, 620))
        self.assertEqual(
            timesheet_lines([shift]),
            ["Ana: 1 shift, 1.3 hours"]
        )

    def test_ties_sorted_by_name(self):
        lines = timesheet_lines([
            make_shift("Zoya", "mon", 9, 10),
            make_shift("Ana", "mon", 9, 10)
        ])
        self.assertTrue(lines[0].startswith("Ana"))

    def test_empty_list(self):
        with self.assertRaises(ProjectError):
            timesheet_lines([])

    def test_blank_worker(self):
        blank = make_shift("  ", "mon", 9, 10)
        with self.assertRaises(ProjectError):
            timesheet_lines([blank])


if __name__ == "__main__":
    unittest.main()
